def recherche_avec_compteur(liste, cible):
    comparaisons = 0
    for valeur in liste:
        comparaisons += 1
        if valeur == cible:
            break
    return comparaisons

notes = [12, 8, 15, 10, 17]
print(recherche_avec_compteur(notes, 15))
print(recherche_avec_compteur(notes, 20))

def paires(n):
    operations = 0
    for i in range(n):
        for j in range(n):
            operations += 1
    return operations

for n in [10, 20, 40]:
    print(n, paires(n))

