def croissance(avant, apres):
    rapport = apres / avant
    if rapport < 1.5:
        return "constante"
    if rapport < 3:
        return "linéaire"
    return "quadratique"

def mesurer(n):
    lineaire = 0
    for i in range(n):
        lineaire += 1
    quadratique = 0
    for i in range(n):
        for j in range(n):
            quadratique += 1
    logarithmique = 0
    m = n
    while m > 1:
        m //= 2
        logarithmique += 1
    return {"lineaire": lineaire, "quadratique": quadratique, "logarithmique": logarithmique}
